// Aggregate today's Price_Log + Price_Index data into a structured summary for the AI report.
// This node receives Cron trigger (1 item). It reads from Price_Log and Price_Index via
// static data set earlier — or re-reads the passed items.

// Since this is a separate workflow (fires at 08:00), we read both sheets independently.
// The Cron trigger output[0] goes to both Read nodes via split.
// We use $getWorkflowStaticData to merge them after both reads.
// NOTE: Because of the dual-read architecture, this code node is called AFTER both reads
// have completed and merged. See connections: both reads feed into a Merge node, then here.

const allItems = $input.all();
const today = new Date().toISOString().split('T')[0];

// Separate Price_Log vs Price_Index rows by checking which fields exist
const priceLogRows   = allItems.map(i => i.json).filter(r => r.Platform && r.Raw_Product_Name);
const priceIndexRows = allItems.map(i => i.json).filter(r => r.Index_Percent !== undefined);

// ── Filter to TODAY only ──────────────────────────────
const todayLog   = priceLogRows.filter(r => r.Date === today);
const todayIndex = priceIndexRows.filter(r => r.Date === today);

if (todayLog.length === 0) {
  return [{ json: {
    _no_data: true,
    summary: `No Price_Log data found for today (${today}). Scraper may not have run yet.`,
    today
  }}];
}

// ── Build aggregates ──────────────────────────────────
const platforms   = [...new Set(todayLog.map(r => r.Platform))];
const totalSKUs   = todayLog.length;
const ourSKUs     = todayLog.filter(r => r.Is_Ours === true || r.Is_Ours === 'TRUE');
const competitorSKUs = todayLog.filter(r => !ourSKUs.includes(r));

// OOS analysis
const ourOOS      = ourSKUs.filter(r => r.In_Stock === false || r.In_Stock === 'FALSE');
const competitorOOS = competitorSKUs.filter(r => r.In_Stock === false || r.In_Stock === 'FALSE');
const persistentOOS = ourOOS.filter(r => r.First_Seen_OOS &&
  (Date.now() - new Date(r.First_Seen_OOS)) / 36e5 > 48);

// Promotions active today
const activePromos = todayLog.filter(r => r.Promo_Type && r.Promo_Type !== 'None');

// Price Index highlights (top 3 deviations from 100)
const indexHighlights = todayIndex
  .filter(r => r.Index_Percent)
  .sort((a, b) => Math.abs(100 - b.Index_Percent) - Math.abs(100 - a.Index_Percent))
  .slice(0, 5);

// ── Build data summary for AI ──────────────────────────
const summary = {
  report_date: today,
  platforms_monitored: platforms,
  totals: {
    products_tracked: totalSKUs,
    corona_products: ourSKUs.length,
    competitor_products: competitorSKUs.length
  },
  oos_summary: {
    corona_oos: ourOOS.map(r => ({ sku: r.Matched_SKU, platform: r.Platform, since: r.First_Seen_OOS, category: r.Category })),
    competitor_oos: competitorOOS.map(r => ({ brand: r.Brand, product: r.Raw_Product_Name, platform: r.Platform, category: r.Category })),
    critical_persistent_oos: persistentOOS.map(r => ({ sku: r.Matched_SKU, platform: r.Platform, since: r.First_Seen_OOS, hours: Math.round((Date.now() - new Date(r.First_Seen_OOS)) / 36e5) }))
  },
  promotions: activePromos.map(r => ({ brand: r.Brand, product: r.Raw_Product_Name, platform: r.Platform, promo_type: r.Promo_Type, discount: r.Discount_Percent, current_price: r.Price_EGP, original_price: r.Original_Price_EGP })),
  price_index_highlights: indexHighlights.map(r => ({ sku: r.SKU, platform: r.Platform, category: r.Category, our_price: r.Our_Price, competitor_price: r.Competitor_Price, competitor_brand: r.Competitor_Brand, index_percent: r.Index_Percent }))
};

return [{ json: { summary_json: JSON.stringify(summary, null, 2), today, _no_data: false } }];

