// Format the AI-generated report for Telegram (4096 char limit per message)
// Split into multiple messages if needed.

const rawReport = $json.output || $json.text || 'Report generation failed.';
const today = new Date().toLocaleString('ar-EG', { timeZone: 'Africa/Cairo', dateStyle: 'full' });

// Telegram max message size is 4096 chars. Split if over limit.
const MAX_LENGTH = 4000;

if (rawReport.length <= MAX_LENGTH) {
  return [{ json: {
    message_1: rawReport,
    message_count: 1,
    date_ar: today
  }}];
}

// Split at paragraph boundaries
const parts = [];
let remaining = rawReport;
while (remaining.length > MAX_LENGTH) {
  const splitAt = remaining.lastIndexOf('\n\n', MAX_LENGTH);
  const cutAt = splitAt > 0 ? splitAt : MAX_LENGTH;
  parts.push(remaining.substring(0, cutAt).trim());
  remaining = remaining.substring(cutAt).trim();
}
if (remaining) parts.push(remaining);

const result = { message_count: parts.length, date_ar: today };
parts.forEach((p, i) => { result[`message_${i + 1}`] = p; });

return [{ json: result }];
